$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$migration = Decode ""
$reviewsApi = Decode ""
$groupReviewApi = Decode ""
$groupReviewPage = Decode ""
$oldCompletion = Decode ""
$newCompletion = Decode ""
$groupActionFunction = Decode ""
$groupCompletedGuard = Decode "ICAgICAgLy8gS0xZWF9HUk9VUF9SRVZJRVdfQ0hJTERfR1VBUkRfMTJfODgKICAgICAgaWYgKAogICAgICAgIGJvb2tpbmcuYm9va2luZ19ncm91cF9pZAogICAgICApIHsKICAgICAgICBjb250aW51ZTsKICAgICAgfQo="
$groupActionCall = Decode "CiAgICBhd2FpdCBhZGRDbGllbnRHcm91cFJldmlld0FjdGlvbnMoCiAgICAgIHByb2ZpbGUsCiAgICAgIGFjdGlvbk1hcAogICAgKTs="

$migrationPath = Join-Path $root "supabase\migrations\20260812205500_klyx_group_review_12_88.sql"
$reviewsApiPath = Join-Path $root "app\api\reviews\route.ts"
$groupReviewApiPath = Join-Path $root "app\api\group-reviews\route.ts"
$groupReviewPagePath = Join-Path $root "app\reviews\group\[groupId]\page.tsx"
$groupMissionPagePath = Join-Path $root "app\booking-groups\[id]\page.tsx"
$brainPath = Join-Path $root "lib\brain-actions.ts"

foreach ($path in @($reviewsApiPath, $groupMissionPagePath, $brainPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "Fichier requis introuvable : $path"
    }
}

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $migrationPath) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $groupReviewApiPath) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $groupReviewPagePath) | Out-Null

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

foreach ($path in @($reviewsApiPath, $groupMissionPagePath, $brainPath)) {
    Copy-Item -LiteralPath $path -Destination ($path + ".bak-12-88-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($migrationPath, $migration, $utf8)
[System.IO.File]::WriteAllText($reviewsApiPath, $reviewsApi, $utf8)
[System.IO.File]::WriteAllText($groupReviewApiPath, $groupReviewApi, $utf8)
[System.IO.File]::WriteAllText($groupReviewPagePath, $groupReviewPage, $utf8)

# ===========================================================
# GROUP MISSION PAGE CTA
# ===========================================================

$missionPage = [System.IO.File]::ReadAllText($groupMissionPagePath)

if (-not $missionPage.Contains("KLYX_GROUP_REVIEW_CTA_12_88")) {
    if (-not $missionPage.Contains($oldCompletion)) {
        throw "12.88 : bloc completion 12.87 introuvable."
    }

    $missionPage = $missionPage.Replace($oldCompletion, $newCompletion)
}

[System.IO.File]::WriteAllText($groupMissionPagePath, $missionPage, $utf8)

# ===========================================================
# ACTION CENTER
# ===========================================================

$brain = [System.IO.File]::ReadAllText($brainPath)

if (-not $brain.Contains("KLYX_GROUP_REVIEW_ACTIONS_12_88")) {
    $providerIndex = $brain.IndexOf("async function addProviderActions")

    if ($providerIndex -lt 0) {
        throw "12.88 : addProviderActions introuvable."
    }

    $brain = $brain.Insert($providerIndex, $groupActionFunction)
}

if (-not $brain.Contains("KLYX_GROUP_REVIEW_CHILD_GUARD_12_88")) {
    $clientStart = $brain.IndexOf("function addClientBookingActions")
    $providerStart = $brain.IndexOf("async function addProviderActions", $clientStart)

    if ($clientStart -lt 0 -or $providerStart -lt 0) {
        throw "12.88 : fonction client actions introuvable."
    }

    $clientBlock = $brain.Substring($clientStart, $providerStart - $clientStart)

    $match = [regex]::Match(
        $clientBlock,
        '(?ms)(^\s*if\s*\(\s*booking\.status\s*===\s*"completed"\s*\)\s*\{)'
    )

    if (-not $match.Success) {
        throw "12.88 : action review_completed individuelle introuvable."
    }

    $insertAt = $clientStart + $match.Index + $match.Length

    $brain = $brain.Insert($insertAt, "`n" + $groupCompletedGuard)
}

if (-not $brain.Contains("await addClientGroupReviewActions(")) {
    $match = [regex]::Match(
        $brain,
        '(?ms)addClientBookingActions\(\s*bookings,\s*actionMap\s*\);'
    )

    if (-not $match.Success) {
        throw "12.88 : appel addClientBookingActions introuvable."
    }

    $brain = $brain.Insert($match.Index + $match.Length, $groupActionCall)
}

[System.IO.File]::WriteAllText($brainPath, $brain, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.88 APPLIQUE"
Write-Host "======================================"
Write-Host "Avis groupe unique : OK"
Write-Host "Avis enfants groupes : BLOQUES"
Write-Host "KLYX Score recalcule : OK"
Write-Host "Action Center groupe : OK"
Write-Host "Avis automatique : NON"
Write-Host "======================================"
Write-Host ""
